# tools/grammar-pages/pages.py - the interactive grammar pages, written here, saved as js/grammar-pages.js
#   python3 tools/grammar-pages/pages.py
# A page: line (the rule in one line), words (links to Vocab), steps (the See-it tools, see js/grammar-tools.js),
# practice (choose / build / spot, see js/grammar-practice.js) and drill (the typing part: [question, answer, rule]).
# Keys are the course ids: grammar lessons by number ('1'), verb lessons with a v ('v1').
import json, os
R = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
VOC = lambda n, name: f'<a class="text-indigo-700 font-semibold underline" href="vocab.html?topic=theme:{n}">Vocab {n} · {name}</a>'
C = lambda q, en, opts, a, why, hint: {'q': q, 'en': en, 'opts': opts, 'a': a, 'why': why, 'hint': hint}
B = lambda en, tiles, trap, why, hint: {'en': en, 'tiles': tiles, 'trap': trap, 'why': why, 'hint': hint}
S = lambda words, bad, fix, hint, look, say=None: {'words': words, 'bad': bad, 'fix': fix, 'hint': hint, 'look': look, **({'say': say} if say else {})}
def T(*tiles):   # swap tiles: 'text' or ('text', kind) or ('key', 'text', kind)
    out = []
    for i, t in enumerate(tiles):
        if isinstance(t, str): out.append([f't{i}:{t}', t])
        elif len(t) == 2: out.append([f't{i}:{t[0]}', t[0], t[1]])
        else: out.append(list(t))
    return out
CARD = lambda t, box, why='', en='', say='': {k: v for k, v in {'t': t, 'box': box, 'why': why, 'en': en, 'say': say}.items() if v}
FLIP = lambda a, b, tag='', en='': {k: v for k, v in {'a': a, 'b': b, 'tag': tag, 'en': en}.items() if v}

